css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .62); position: relative; overflow: hidden; border-radius: 6px; }
.loader .plate { position: absolute; left: 0; right: 0; bottom: 8%; height: 34%; background: linear-gradient(color-mix(in srgb, #000 20%, var(--accent)), color-mix(in srgb, #000 45%, var(--accent))); }
.loader .seam { position: absolute; left: 6%; bottom: 38%; height: 6%; width: 0; border-radius: 3px; background: linear-gradient(90deg, var(--accent-2), color-mix(in srgb, #fff 40%, var(--accent-2))); box-shadow: 0 0 10px var(--accent-2); animation: weld-seam calc(var(--loader-speed) * 3) linear infinite; }
.loader .torch { position: absolute; bottom: 44%; left: 6%; width: 9%; height: 46%; border-radius: 3px; background: linear-gradient(#e2e8f0, #475569); transform: rotate(18deg); animation: weld-move calc(var(--loader-speed) * 3) linear infinite; }
.loader .flash { position: absolute; bottom: 30%; left: 4%; width: 14%; height: 26%; border-radius: 50%; background: radial-gradient(circle, color-mix(in srgb, #fff 80%, var(--accent-2)), transparent 68%); animation: weld-flash calc(var(--loader-speed) * .18) steps(1, end) infinite, weld-move calc(var(--loader-speed) * 3) linear infinite; }
.loader i { position: absolute; bottom: 38%; left: 8%; width: 4%; height: 4%; border-radius: 50%; background: var(--accent-2); opacity: 0; animation: weld-spark calc(var(--loader-speed) * .6) ease-out infinite, weld-move calc(var(--loader-speed) * 3) linear infinite; }
.loader i:nth-of-type(1) { bottom: 40%; }
.loader i:nth-of-type(2) { bottom: 34%; left: 11%; animation-delay: calc(var(--loader-speed) * .2), 0s; }
.loader i:nth-of-type(3) { bottom: 44%; left: 5%; animation-delay: calc(var(--loader-speed) * .4), 0s; }
@keyframes weld-seam { 0% { width: 0; opacity: 1; } 82% { width: 84%; opacity: 1; } 94%, 100% { width: 84%; opacity: 0; } }
@keyframes weld-move { 0% { transform: translateX(0) rotate(18deg); } 82%, 100% { transform: translateX(calc(var(--loader-size) * .78)) rotate(18deg); } }
@keyframes weld-flash { 0%, 49% { opacity: 1; transform: scale(1); } 50%, 100% { opacity: .35; transform: scale(.7); } }
@keyframes weld-spark { 0% { opacity: 0; } 12% { opacity: 1; } 100% { opacity: 0; }  }
